/**
 * The runtime's service worker.
 *
 * What makes a built app OPEN without a signal and show the last thing it saw.
 * Holding a WRITE until the signal returns is the queue's job, not this file's
 * — see `resources/js/runtime/offlineQueue.ts`.
 *
 * Hand-written rather than generated by Workbox, because the caching this needs
 * is three rules long and a build-time dependency to express them would cost
 * more than it saves. It also keeps the file readable by whoever debugs it at
 * 2am with a technician on the phone.
 *
 * THREE RULES, all load-bearing:
 *
 *  1. It is registered at the root so it can serve the runtime's own document,
 *     but it only ANSWERS for `/r/…`, `/a/…` and immutable build assets.
 *     Everything else — the admin panel, the builder, auth, every API — falls
 *     straight through to the network. A stale admin screen is worse than no
 *     admin screen, and a cached auth response is a bug with a CVE number.
 *
 *  2. Only GET, only 200, and never a response the server marked `no-store`.
 *     That last one is how an app says which of its data may not sit on a
 *     device at all (`settings.offline`) — decided server-side, so a worker
 *     installed last month honours it as well as one installed today.
 *
 *  3. Nothing is kept forever. Past the retention bound a page is dropped
 *     rather than served, because a phone left in a drawer should eventually
 *     stop holding somebody's customer list.
 */

const VERSION = 'v1';

/** Runtime documents: the HTML shell of a page under /r or /a. */
const SHELL = `sapiensly-shell-${VERSION}`;

/** Content-hashed build output. Immutable by construction. */
const ASSETS = `sapiensly-assets-${VERSION}`;

/** Inertia's JSON — including the deferred `blockData` follow-up. */
const DATA = `sapiensly-data-${VERSION}`;

const OURS = [SHELL, ASSETS, DATA];

/** Stamped onto everything we store, and read back by the offline banner. */
const CACHED_AT = 'x-sapiensly-cached-at';

/**
 * How long tenant rows may live on this device.
 *
 * A retention bound, not a freshness one — the offline banner already says how
 * old what you are looking at is, so staleness is handled by telling the truth
 * about it. This is about the OTHER risk: a phone left in a drawer, or lost,
 * still holding somebody's customer list a year later.
 *
 * Thirty days, and the number is a judgement: long enough that no realistic
 * stretch of field work loses its data, short enough that a forgotten device
 * eventually forgets. Past it a cached page is dropped rather than served —
 * handing somebody month-old work orders is worse than an app that will not
 * open, which is the same trade the network-first rule already makes.
 *
 * Note what this does NOT touch: the write queue. Those are somebody's unsent
 * work and ageing them out would be silently destroying it.
 */
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;

/** Set on a response we served from the cache, so the page can say so. */
const FROM_CACHE = 'x-sapiensly-from-cache';

self.addEventListener('install', (event) => {
    // Nothing to precache: build assets are content-hashed and cached on first
    // use, and precaching them would need the build manifest injected here.
    event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        (async () => {
            const names = await caches.keys();
            await Promise.all(
                names
                    .filter((name) => name.startsWith('sapiensly-') && !OURS.includes(name))
                    .map((name) => caches.delete(name)),
            );
            await forgetWhatIsTooOld();
            await self.clients.claim();
        })(),
    );
});

/**
 * Drop everything past the retention bound.
 *
 * On activate, which is every time the worker starts — so a device that has
 * been closed for two months forgets on the first open rather than on the first
 * request for each page. Assets are exempt: `/build/` output is content-hashed
 * and carries nobody's data.
 */
async function forgetWhatIsTooOld() {
    for (const name of [SHELL, DATA]) {
        const cache = await caches.open(name);
        for (const request of await cache.keys()) {
            const hit = await cache.match(request);
            if (hit && !fresh(hit, Date.now())) {
                await cache.delete(request);
            }
        }
    }
}

/**
 * Whether a stored response is still within the retention bound.
 *
 * An entry with NO stamp is treated as fresh: it predates this rule, and
 * deleting somebody's cache because we changed our own bookkeeping would be the
 * wrong way round. The sweep above re-stamps nothing, so those age out the next
 * time the page is fetched.
 */
function fresh(response, now) {
    const stamp = response.headers.get(CACHED_AT);
    if (!stamp) {
        return true;
    }

    const at = Date.parse(stamp);

    return Number.isNaN(at) || now - at < MAX_AGE_MS;
}

/**
 * Sign-out purges everything. The cache holds rows this person was allowed to
 * see; the next person at this device is not necessarily the same person.
 */
self.addEventListener('message', (event) => {
    if (event.data?.type !== 'sapiensly:purge') {
        return;
    }

    event.waitUntil(
        (async () => {
            const names = await caches.keys();
            await Promise.all(
                names.filter((name) => name.startsWith('sapiensly-')).map((name) => caches.delete(name)),
            );
            event.source?.postMessage({ type: 'sapiensly:purged' });
        })(),
    );
});

self.addEventListener('fetch', (event) => {
    const request = event.request;

    if (request.method !== 'GET') {
        return;
    }

    const url = new URL(request.url);

    // Somebody else's origin is somebody else's problem.
    if (url.origin !== self.location.origin) {
        return;
    }

    if (isImmutableAsset(url)) {
        event.respondWith(cacheFirst(request, ASSETS));

        return;
    }

    if (!isRuntimePath(url)) {
        return; // admin, builder, auth, APIs — straight to the network.
    }

    event.respondWith(networkFirst(request, isInertiaRequest(request) ? DATA : SHELL));
});

/** Hashed build output and the static fonts the runtime renders with. */
function isImmutableAsset(url) {
    return url.pathname.startsWith('/build/') || url.pathname.startsWith('/fonts/');
}

/** The two mounts a built app is served from: authenticated and public portal. */
function isRuntimePath(url) {
    return /^\/(r|a)\//.test(url.pathname);
}

function isInertiaRequest(request) {
    return request.headers.get('X-Inertia') === 'true';
}

/**
 * The cache key.
 *
 * Inertia asks for the SAME url twice: once for the page and again for the
 * deferred props (`blockData`), told apart only by a request header. Keyed by
 * url alone the second answer would overwrite the first and the page would come
 * back from cache with no shell — so the partial header is part of the key.
 */
function cacheKey(request) {
    const partial = request.headers.get('X-Inertia-Partial-Data');

    return partial ? `${request.url}#partial=${partial}` : request.url;
}

async function cacheFirst(request, cacheName) {
    const cache = await caches.open(cacheName);
    const hit = await cache.match(request);

    if (hit) {
        return hit;
    }

    const response = await fetch(request);
    if (storable(response)) {
        await cache.put(request, await stamp(response.clone()));
    }

    return response;
}

/**
 * Network first, cache as the fallback — never the other way round.
 *
 * Fresh data whenever there is a signal is not negotiable: a technician acting
 * on a cached work order that was reassigned an hour ago is a worse failure
 * than an app that will not open.
 */
async function networkFirst(request, cacheName) {
    const cache = await caches.open(cacheName);
    const key = cacheKey(request);

    try {
        const response = await fetch(request);

        if (storable(response)) {
            await cache.put(key, await stamp(response.clone()));
        }

        return response;
    } catch (networkError) {
        const hit = await cache.match(key);

        // Checked on the way out as well as swept on activate: the sweep runs
        // when the worker starts, and a tab left open for weeks never restarts
        // it. Without this the bound would hold for every device except the one
        // that never closed the app.
        if (hit && fresh(hit, Date.now())) {
            return withHeaders(hit, { [FROM_CACHE]: '1' });
        }

        if (hit) {
            await cache.delete(key);
        }

        throw networkError;
    }
}

/**
 * What we are allowed to keep.
 *
 * `no-store` is the server saying "this answer is for this request only", and
 * the runtime uses it for anything it does not want replayed. Honour it.
 */
function storable(response) {
    if (!response || response.status !== 200 || response.type === 'opaque') {
        return false;
    }

    return !(response.headers.get('Cache-Control') || '').includes('no-store');
}

async function stamp(response) {
    return withHeaders(response, { [CACHED_AT]: new Date().toISOString() });
}

/**
 * A Response's headers are immutable, so adding one means rebuilding it. The
 * body is read here — pass a clone.
 */
async function withHeaders(response, extra) {
    const headers = new Headers(response.headers);
    for (const [name, value] of Object.entries(extra)) {
        headers.set(name, value);
    }

    return new Response(await response.blob(), {
        status: response.status,
        statusText: response.statusText,
        headers,
    });
}

/**
 * The decisions, exposed for tests.
 *
 * A service worker is a script the browser runs, not a module anything can
 * import — so the two rules that matter (what it is allowed to ANSWER for, and
 * what it is allowed to KEEP) would otherwise be verifiable only by driving a
 * real browser offline. That test is worth having and is not the one you want
 * to run on every commit.
 */
self.__swInternals = { isRuntimePath, isImmutableAsset, isInertiaRequest, cacheKey, storable, fresh, MAX_AGE_MS };
